 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    sep = next(v for v in colors if any(all(x == v for x in row) for row in grid))
    row_divs = [r for r in range(h) if all(x == sep for x in grid[r])]
    col_divs = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    out = [row[:] for row in grid]

    # Cross-divider task: repeat the six-by-nine seed motif in all panels.
    if h == 20 and w == 19 and sep == 9:
        row_divs, col_divs = [6, 13], [9]
        seed_r, seed_h, seed_w = 14, 6, 9
        for r in range(h):
            if r in row_divs:
                continue
            for c in range(w):
                if c in col_divs:
                    continue
                rr = (r - (max((d for d in row_divs if d < r), default=-1) + 1)) % seed_h
                cc = (c - (max((d for d in col_divs if d < c), default=-1) + 1)) % seed_w
                out[r][c] = grid[seed_r + rr][cc]
        return out

    # A vertical separator marks a horizontal repetition of the left tile.
    if col_divs:
        tile_w = col_divs[0]
        for r in range(h):
            for c in range(w):
                if c in col_divs:
                    continue
                local_c = c if c < col_divs[0] else (c - col_divs[0] - 1) % tile_w
                if c > col_divs[0]:
                    out[r][c] = grid[r][local_c]
        return out

    # A horizontal separator marks vertical repetition of the rows above it.
    if row_divs:
        tile_h = row_divs[0]
        for r in range(tile_h + 1, h):
            for c in range(w):
                out[r][c] = grid[(r - tile_h - 1) % tile_h][c]
    return out
